import assert from 'node:assert';
import test from 'node:test';
import { createState, frame, UP, DOWN } from '../game/neon.js';

test('D1: Ball should bounce off a brick', () => {
  const state = createState(1);
  // Place ball such that it collides with the first brick in the next frame
  // Brick 0 is at (offsetX, BRICK_TOP)
  // let's just force the collision
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2; // Just above the brick
  state.ball.vy = 100; // Moving down

  // Simulate one frame. 
  // Note: frame() currently handles collision, not step()
  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {}
  };

  frame(ctx, state);

  // Currently, the brick is killed, but the ball's vy is NOT changed.
  // It should be inverted (vy should become negative).
  assert.strictEqual(state.ball.vy, -100, 'Ball vy should be inverted after hitting brick');
});

import assert from 'node:assert';
import test from 'node:test';
import { createState, frame, UP, DOWN } from '../game/neon.js';

const ctx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {}
};

test('D1: Missing bounce', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100;
  frame(ctx, state);
  assert.strictEqual(state.ball.vy, -100, 'Ball vy should be inverted');
});

test('D2: Sticky collision (naïve correction failure)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Ball is deep inside the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 5;
  state.ball.vy = 100;

  // First frame: bounce (if naïve)
  frame(ctx, state);
  // If naïve, vy became -100.

  // Second frame: ball is still inside. If it bounces again, it's sticky.
  // We simulate another frame with the same position.
  frame(ctx, state); 

  // After two frames, if it's still colliding, it should have’t inverted back to 100.
  // But actually, if it's sticky, it'll flip back and forth.
  // The correct behavior is that after the first bounce, it's pushed out and no longer collides.
  assert.strictEqual(state.ball.vy, -100, 'Ball should not bounce again if it was properly resolved');
});

test('D3: Tunneling', () => {
  const state = createState(10); // High speed
  const brick = state.bricks[0];
  // Position the ball so it jumps over the brick in one frame
  // Brick.y = 48, Brick.h = 20. Bottom = 68.
  // Ball.r = 7.
  // Let's place ball at y=40, vy=1000.
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 1000; 

  // In the actual game, step() is called, then frame().
  // We need to simulate the jump.
  const dt = 0.05;
  state.ball.y += state.ball.vy * dt; // 40 + 50 = 90.
  // Now ball.y = 90. Ball.y - r = 83. Brick.bottom = 68.
  // The ball is now below the brick.

  frame(ctx, state);

  // If tunneling occurs, brick.alive is still true.
  assert.strictEqual(brick.alive, false, 'Ball should have hit the brick despite the jump');
});

test('D4: Corner resolution', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Hit the top-left corner
  state.ball.x = brick.x - 2;
  state.ball.y = brick.y - 2;
  state.ball.vx = 10;
  state.ball.vy = 10;

  frame(ctx, state);

  assert.strictEqual(state.ball.vx, -10, 'Ball vx should be inverted at corner');
  assert.strictEqual(state.ball.vy, -10, 'Ball vy should be inverted at corner');
});

test('D5: Seam collision', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1]; // Adjacent brick

  // Ball overlaps both bricks
  state.ball.x = brick1.x + brick1.w - 2; 
  state.ball.y = brick1.y + 5;
  state.ball.vy = 100;

  frame(ctx, state);

  // Should only bounce once
  assert.strictEqual(state.ball.vy, -100, 'Ball should only bounce once when hitting a seam');
});

