// Bricks: collision + bounce + score + drawing, all in one place.
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  let collided = collides(state.ball, brick);

  // Swept AABB check for tunneling (D3)
  if (!collided && state.ball.px !== undefined) {
    const minX = Math.min(state.ball.px - state.ball.r, state.ball.x - state.ball.r);
    const maxX = Math.max(state.ball.px + state.ball.r, state.ball.x + state.ball.r);
    const minY = Math.min(state.ball.py - state.ball.r, state.ball.y - state.ball.r);
    const maxY = Math.max(state.ball.py + state.ball.r, state.ball.y + state.ball.r);

    if (maxX > brick.x && minX < brick.x + brick.w && maxY > brick.y && minY < brick.y + brick.h) {
      // Potential tunnel. Check if it actually crossed the brick's boundaries.
      // Since we're in a 2D game and bricks are axis-aligned, we can just check
      // if the ball was on one side and is now on the other.
      const wasAbove = state.ball.py + state.ball.r <= brick.y;
      const isBelow = state.ball.y - state.ball.r >= brick.y + brick.h;
      const wasBelow = state.ball.py - state.ball.r >= brick.y + brick.h;
      const isAbove = state.ball.y + state.ball.r <= brick.y;
      const wasLeft = state.ball.px + state.ball.r <= brick.x;
      const isRight = state.ball.x - state.ball.r >= brick.x + brick.w;
      const wasRight = state.ball.px - state.ball.r >= brick.x + brick.w;
      const isLeft = state.ball.x + state.ball.r <= brick.x;

      if ((wasAbove && isBelow) || (wasBelow && isAbove) || (wasLeft && isRight) || (wasRight && isLeft)) {
        collided = true;
      }
    }
  }

  if (collided) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Collision Resolution (D1, D2, D4, D5)
    const penLeft = (state.ball.x + state.ball.r) - brick.x;
    const penRight = (brick.x + brick.w) - (state.ball.x - state.ball.r);
    const penTop = (state.ball.y + state.ball.r) - brick.y;
    const penBottom = (brick.y + brick.h) - (state.ball.y - state.ball.r);

    const minPen = Math.min(penLeft, penRight, penTop, penBottom);

    if (minPen === penLeft) {
      state.ball.x = brick.x - state.ball.r;
      state.ball.vx = -Math.abs(state.ball.vx);
    } else if (minPen === penRight) {
      state.ball.x = brick.x + brick.w + state.ball.r;
      state.ball.vx = Math.abs(state.ball.vx);
    } else if (minPen === penTop) {
      state.ball.y = brick.y - state.ball.r;
      state.ball.vy = Math.abs(state.ball.vy);
    } else if (minPen === penBottom) {
      state.ball.y = brick.y + brick.h + state.ball.r;
      state.ball.vy = -Math.abs(state.ball.vy);
    }
  }

  ctx.fillStyle = brickColor(brick.row);

