edits.newText:
if (collided) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Collision Resolution (D1, D2, D4, D5)
  let vx = state.ball.vx;
  let vy = state.ball.vy;
  let { x, y, r } = state.ball;

  const penLeft = (x + r) - brick.x;
  const penRight = (brick.x + brick.w) - (x - r);
  const penTop = (y + r) - brick.y;
  const penBottom = (brick.y + brick.h) - (y - r);

  if (collides(state.ball, brick)) {
    const minPen = Math.min(penLeft, penRight, penTop, penBottom);
    const isLeft = minPen === penLeft;
    const isRight = minPen === penRight;
    const isTop = minPen === penTop;
    const isBottom = minPen === penBottom;

    const axes = [];
    if (isLeft) axes.push('left');
    if (isRight) axes.push('right');
    if (isTop) axes.push('top');
    if (isBottom) axes.push('bottom');

    if (axes.length > 1) {
      if (isLeft) x = brick.x - r;
      if (isRight) x = brick.x + brick.w + r;
      if (isTop) y = brick.y - r;
      if (isBottom) y = brick.y + brick.h + r;
      vx = -vx;
      vy = -vy;
    } else if (isLeft) {
      x = brick.x - r;
      vx = -Math.abs(vx);
    } else if (isRight) {
      x = brick.x + brick.w + r;
      vx = Math.abs(vx);
    } else if (isTop) {
      y = brick.y - r;
      vy = -Math.abs(vy);
    } else if (isBottom) {
      y = brick.y + brick.h + r;
      vy = Math.abs(vy);
    }
  } else if (state.ball.px !== undefined) {
    // Tunneling resolution: determine face based on movement
    const wasAbove = state.ball.py + r <= brick.y;
    const isAbove = y + r <= brick.y;
    const wasBelow = state.ball.py - r >= brick.y + brick.h;
    const isBelow = y - r >= brick.y + brick.h;
    const wasLeft = state.ball.px + r <= brick.x;
    const isLeft = x - r >= brick.x + brick.w; // Wait, this is wrong.
    const wasRight = state.ball.px - r >= brick.x + brick.w;
    const isRight = x + r <= brick.x;

    // Simplified tunneling: just check the primary axis of movement
    if (Math.abs(vy) > Math.abs(vx)) {
      if (wasBelow && isAbove) {
        // Hit bottom face from below (but now we are above)
        // Wait, if we are above, we should have hit the bottom face of the brick
        // and been reflected DOWN.
        vy = Math.abs(vy);
        y = brick.y + brick.h + r;
      } else if (wasAbove && isBelow) {
        vy = -Math.abs(vy);
        y = brick.y - r;
      }
    } else {
      if (wasRight && isLeft) {
        vx = Math.abs(vx);
        x = brick.x + brick.w + r;
      } else if (wasLeft && isRight) {
        vx = -Math.abs(vx);
        x = brick.x - r;
      }
    }
  }

  state.ball.x = x;
  state.ball.y = y;
  state.ball.vx = vx;
  state.ball.vy = vy;
}

